    'Songs', 
    'html', 
    'ଶ୍ରୀ ଭୋଗ ନିବେଦନ କୀର୍ତ୍ତନ', 
    'ଶ୍ରୀଲ ଭକ୍ତି ବିନୋଦ ଠାକୁରଙ୍କ ରଚନା', 
    $json${"verses":[{"id":1,"lyric":"ଭଜ ଭକତବତ୍ସଲ ଶ୍ରୀଗୌରହରି ।\nଶ୍ରୀଗୌରହରି ସୋହି ଗୋଷ୍ଠବିହାରୀ,\nନନ୍ଦ-ଯଶୋମତୀ ଚିତ୍ତହାରୀ ।।୧।।","translation":"କେବଳ ସେହି ଶ୍ରୀ ଗୌରହରିଙ୍କୁ ଭଜନ କର, ଯିଏ ନିଜ ଭକ୍ତମାନଙ୍କ ପ୍ରତି ସର୍ବଦା ବତ୍ସଳ (ସ୍ନେହଶୀଳ) । ସେ ହେଉଛନ୍ତି ସେହି ସ୍ୱୟଂ ଭଗବାନ ଶ୍ରୀକୃଷ୍ଣ, ଯିଏ ବ୍ରଜର ଗୋଷ୍ଠରେ କ୍ରୀଡ଼ା କରୁଥିଲେ ଏବଂ ନନ୍ଦ ଓ ଯଶୋଦାଙ୍କ ହୃଦୟ ଚୋରି କରିଥିଲେ। କେବଳ ସେହି ଗୋବିନ୍ଦ, ଗୋବିନ୍ଦ, ଗୋପାଳଙ୍କୁ ଭଜନ କର!","wordMeanings":[{"word":"ଭଜ","meaning":"କେବଳ ଭଜନ କର"},{"word":"ଭକତ-ବତ୍ସଳ","meaning":"ଯିଏ ନିଜ ଭକ୍ତମାନଙ୍କ ପ୍ରତି ଅତି ସ୍ନେହୀ"},{"word":"ଶ୍ରୀ-ଗୌରହରି","meaning":"ପ୍ରଭୁ ଚୈତନ୍ୟ"},{"word":"ଶ୍ରୀ-ଗୌରହରି","meaning":"ଏହି ଶ୍ରୀ ଗୌରହରି"},{"word":"ସୋହି","meaning":"ସେହି ସମାନ"},{"word":"ଗୋଷ୍ଠ-বিହାରୀ","meaning":"ଯିଏ ଗୋଷ୍ଠ ପ୍ରାଙ୍ଗଣରେ କ୍ରୀଡ଼ା କରନ୍ତି"},{"word":"ନନ୍ଦ-ଯଶୋମତୀ-ଚିତ୍ତ-ହରି","meaning":"ଯିଏ ନନ୍ଦ ମହାରାଜ ଓ ମାତା ଯଶୋଦାଙ୍କ ଚିତ୍ତ ହରଣ କରିଛନ୍ତି।"}]},{"id":2,"lyric":"ବେଲା ହ’ଲୋ ଦାମୋଦର, ଆଇସ ଏଖନ ।\nଭୋଗ-ମନ୍ଦିରେ ବସି’ କରହ ଭୋଜନ ।।୨।।","translation":"ମାତା ଯଶୋଦା କୃଷ୍ଣଙ୍କୁ ଡାକି କହୁଛନ୍ତି, \"ମୋର ପ୍ରିୟ ଦାମୋଦର, ବହୁତ ଡେରି ହୋଇଗଲାଣି। ଦୟାକରି ଏବେ ଆସ, ଭୋଜନ ଗୃହରେ ବସ ଏବଂ ତୁମର ମଧାହ୍ନ ଭୋଜନ ଗ୍ରହଣ କର।\"","wordMeanings":[{"word":"ବେଲା ହୋଲୋ","meaning":"ବହୁତ ବିଳମ୍ବ ହେଲାଣି"},{"word":"ଦାମୋଦର","meaning":"ହେ ଦାମୋଦର!"},{"word":"ଆଇସ ଏଖୋନୋ","meaning":"ଏବେ ଆସ"},{"word":"ଭୋଗ-ମନ୍ଦିରେ","meaning":"ଭୋଜନ ଶାଳାରେ"},{"word":"ବସି'","meaning":"ବସି"},{"word":"କୋରହୋ ଭୋଜନ","meaning":"ଦୟାକରି ଭୋଜନ କର।"}]},{"id":3,"lyric":"ନନ୍ଦେର ନିର୍ଦେଶେ ବୈସେ ଗିରିବରଧାରୀ ।\nବଲଦେବ ସହ ସଖା ବୈସେ ସାରି ସାରି ।।୩।।","translation":"ନନ୍ଦ ମହାରାଜଙ୍କ ନିର୍ଦ୍ଦେଶରେ, ଗୋବର୍ଦ୍ଧନଧାରୀ କୃଷ୍ଣ ଭୋଜନ ପାଇଁ ବସିଲେ ଏବଂ ତାଙ୍କ ପରେ ସମସ୍ତ ଗୋପବାଳକମାନେ କୃଷ୍ଣଙ୍କ ବଡ଼ଭାଇ ଶ୍ରୀ ବଳଦେବଙ୍କ ସହିତ ଧାଡ଼ି ହୋଇ ବସିଲେ।","wordMeanings":[{"word":"ନନ୍ଦେର ନିଦେଶେ","meaning":"ନନ୍ଦ ମହାରାଜଙ୍କ ନିର୍ଦ୍ଦେଶରେ"},{"word":"ବୈସେ","meaning":"ବସନ୍ତି"},{"word":"ଗିରି-ବର-ଧାରୀ","meaning":"ଗୋବର୍ଦ୍ଧନ ଗିରିଧାରୀ"},{"word":"ବଳଦେବ-ସହ","meaning":"ଶ୍ରୀ ବଳଦେବଙ୍କ ସହିତ"},{"word":"ସଖା","meaning":"ଗୋପାଳ ବାଳକମାନେ"},{"word":"ବୈସେ ସାରି ସାରି","meaning":"ଧାଡ଼ି ହୋଇ ବସନ୍ତି।"}]},{"id":4,"lyric":"ଶୁକୁତା ଶାକାଦି ଭାଜି ନାଲିତା କୁଷ୍ମାଣ୍ଡ ।\nଡାଲି ଡ଼ାଲନା ଦୁଗ୍ଧତୁମ୍ବୀ ଦଧି ମୋଚା ଖଣ୍ଡ ।।୪।।","translation":"ସେମାନଙ୍କୁ ପ୍ରଥମେ ଶୁକ୍ତା ଏବଂ ବିଭିନ୍ନ ପ୍ରକାରର ଶାଗ, ସ୍ୱାଦିଷ୍ଟ ଭଜା ଏବଂ ନାଳିତା ଶାଗ ପରଷାଗଲା। ସେମାନଙ୍କୁ କଖାରୁ, ଫଳ ଟୋକେଇ, ଡାଲି ଓ କ୍ଷୀରରେ ପ୍ରସ୍ତୁତ ଛୋଟ ଚୌକୋ ପିଠା, ମନ୍ଦା ଦହି, ଦୁଗ୍ଧ-ଲାଉ ଏବଂ କଦଳୀ ଭଣ୍ଡାରେ ପ୍ରସ୍ତୁତ ବ୍ୟଞ୍ଜନ ମଧ୍ୟ ଦିଆଗଲା।","wordMeanings":[{"word":"ଶୁକ୍ତା","meaning":"ଶୁକ୍ତ (ତିକ୍ତ ବ୍ୟଞ୍ଜନ)"},{"word":"ଶାକ","meaning":"ଶାଗ"},{"word":"ଆଦି","meaning":"ଇତ୍ୟାଦି"},{"word":"ଭାଜି","meaning":"ଭଜା"},{"word":"ନାଲିତା","meaning":"ନାଳିତା ଶାଗ"},{"word":"କୁଷ୍ମାଣ୍ଡ","meaning":"କଖାରୁ"},{"word":"ଡାଲି ଡାଲନା","meaning":"ଡାଲି ଓ ଡାଲମା"},{"word":"ଦୁଗ୍ଧ-ତୁମ୍ବୀ","meaning":"କ୍ଷୀରରେ ରନ୍ଧା ହୋଇଥିବା ଲାଉ"},{"word":"ଦଧି","meaning":"ବହଳ ଦହି"},{"word":"ମୋଚା-ଖଣ୍ଡ","meaning":"କଦଳୀ ଭଣ୍ଡାରୁ ପ୍ରସ୍ତୁତ ବ୍ୟଞ୍ଜନ।"}]},{"id":5,"lyric":"ମୁଦ୍ଗବଡ଼ା ମାଷବଡ଼ା ରୋଟିକା ଘୃତାନ୍ନ ।\nଶଷ୍କୁଲୀ ପିଷ୍ଟକ କ୍ଷୀର ପୁଲି ପାୟସାନ୍ନ ।।୫।।","translation":"ତା'ପରେ ସେମାନେ ମୁଗ ବରା, ବିରି ବରା, ରୋଟି ଏବଂ ଘିଅ-ଭାତ ପାଇଲେ। ଏହାପରେ କ୍ଷୀର, ଚିନି ଓ ରାଶିରେ ପ୍ରସ୍ତୁତ ମିଠା; ଚାଉଳ ଚୂନାର ପିଠା; ରବିଡ଼ି; କ୍ଷୀରରେ ଭାସୁଥିବା ପୁଲି ପିଠା ଏବଂ ଖିରି ପରଷାଗଲା।","wordMeanings":[{"word":"ମୁଦ୍ଗ-ବୋରା","meaning":"ମୁଗ ଡାଲି ବରା"},{"word":"ମାଷ-ବୋରା","meaning":"ବିରି ଡାଲି ବରା"},{"word":"ରୋଟିକା","meaning":"ରୁଟି"},{"word":"ଘୃତାନ୍ନ","meaning":"ଘିଅ ଅନ୍ନ"},{"word":"ଶଷ୍କୁଲି","meaning":"ମିଠା ପିଠା ବିଶେଷ"},{"word":"ପିଷ୍ଟକ","meaning":"ପିଠା"},{"word":"କ୍ଷୀର","meaning":"ବହଳ କ୍ଷୀର"},{"word":"ପୁଲି","meaning":"ପୁଲି ପିଠା"},{"word":"ପାୟସାନ୍ନ","meaning":"କ୍ଷୀରି।"}]},{"id":6,"lyric":"କର୍ପୂର ଅମୃତ କେଲି ରମ୍ଭା କ୍ଷୀରସାର ।\nଅମୃତ ରସାଲା ଅମ୍ଳ ଦ୍ଵାଦଶ ପ୍ରକାର |୬||","translation":"ସେଠାରେ କର୍ପୂର ମିଶ୍ରିତ ଅମୃତ ପରି ସ୍ୱାଦିଷ୍ଟ ଖିରି ମଧ୍ୟ ଥିଲା। କଦଳୀ ଏବଂ ଅମୃତ ପରି ସୁସ୍ୱାଦୁ ଛେନାସର ମଧ୍ୟ ଥିଲା। ସେମାନଙ୍କୁ ତେନ୍ତୁଳି, କାଗଜି ଲେମ୍ବୁ, ମିଠା ଲେମ୍ବୁ, କମଳା ଏବଂ ଡାଳିମ୍ବରେ ପ୍ରସ୍ତୁତ ବାର ପ୍ରକାରର ଖଟା ବ୍ୟଞ୍ଜନ ମଧ୍ୟ ଦିଆଗଲା।","wordMeanings":[{"word":"କର୍ପୂର","meaning":"କର୍ପୂର ବାସିତ"},{"word":"ଅମୃତ-କେଲି","meaning":"ଏକ ପ୍ରକାର ମିଠା"},{"word":"ରମ୍ଭା","meaning":"କଦଳୀ"},{"word":"କ୍ଷୀର-ସାର","meaning":"ସୁଆଦିଆ ଛେନା"},{"word":"ଅମୃତ ରସାଲା","meaning":"ଅମୃତ ପରି ମିଠା ଆମ୍ବ"},{"word":"ଅମ୍ଳ","meaning":"ଖଟା ବ୍ୟଞ୍ଜନ"},{"word":"ଦ୍ୱାଦଶ ପ୍ରକାର","meaning":"ବାର ପ୍ରକାରର।"}]},{"id":7,"lyric":"ଲୁଚି, ଚିନି, ସରପୁରୀ ଲାଡୁ ରସାବଲୀ ।\nଭୋଜନ କରେନ କୃଷ୍ଣ ହୟେ କୁତୂହଲୀ ॥୭॥","translation":"ମଇଦା ଓ ଚିନିରେ ପ୍ରସ୍ତୁତ ପୁରି (puns); କ୍ଷୀରସର ଭର୍ତ୍ତି ପୁରି; ଲାଡୁ ଏବଂ ମିଠା ରସରେ ପଡ଼ିଥିବା ବରା (ରସାବଳି) ମଧ୍ୟ ଥିଲା। କୃଷ୍ଣ ଅତି ଆଗ୍ରହର ସହ ସମସ୍ତ ଖାଦ୍ୟ ଭୋଜନ କଲେ।","wordMeanings":[{"word":"ଲୁଚି ଚିନି","meaning":"ଚିନି ମିଶ୍ରିତ ଲୁଚି"},{"word":"ସରପୁରୀ","meaning":"ସରପୁଳି"},{"word":"ଲାଡୁ","meaning":"ଲଡୁ"},{"word":"ରସାବଳୀ","meaning":"ରସାବଳୀ"},{"word":"ଭୋଜନ କୋରେନ କୃଷ୍ଣ","meaning":"କୃଷ୍ଣ ଭୋଜନ କରନ୍ତି"},{"word":"ହୋଇ କୁତୂହଳୀ","meaning":"ଅତି ଆନନ୍ଦରେ।"}]},{"id":8,"lyric":"ରାଧିକାର ପକ୍ବ ଅନ୍ନ ବିବିଧ ବ୍ୟଞ୍ଜନ ।\nପරମ ଆନନ୍ଦେ କୃଷ୍ଣ କରେନ ଭୋଜନ ॥୮॥","translation":"ଶ୍ରୀମତୀ ରାଧାରାଣୀଙ୍କ ଦ୍ୱାରା ରନ୍ଧାଯାଇଥିବା ଅନ୍ନ, ତରକାରୀ, ମିଠା ଏବଂ ପିଠାକୁ କୃଷ୍ଣ ପରମ ଆନନ୍ଦରେ ଭୋଜନ କଲେ।","wordMeanings":[{"word":"ରାଧିକାର","meaning":"ଶ୍ରୀରାଧାଙ୍କ ଦ୍ୱାରା"},{"word":"ପକ୍କ ଅନ୍ନ","meaning":"ରନ୍ଧା ହୋଇଥିବା ଅନ୍ନ"},{"word":"ବିବିଧ","meaning":"ବିଭିନ୍ନ ପ୍ରକାରର"},{"word":"ବ୍ୟଞ୍ଜନ","meaning":"ତରକାରୀ"},{"word":"ପରମ ଆନନ୍ଦେ","meaning":"ପରମ ଆନନ୍ଦରେ"},{"word":"କୃଷ୍ଣ କୋରେନ ଭୋଜନ","meaning":"କୃଷ୍ଣ ଭୋଜନ କରନ୍ତି।"}]},{"id":9,"lyric":"ଛଲେ ବଲେ ଲାଡୁ ଖାୟ ଶ୍ରୀମଧୁମଙ୍ଗଲ ।\nବଗଲ ବାଜାୟ ଆର ଦେୟ ହରିବୋଲ ॥୯॥","translation":"କୃଷ୍ଣଙ୍କ ହସକୁରୁଥା ବ୍ରାହ୍ମଣ ସଖା ମଧୁମଙ୍ଗଳ, ଯିଏ ଲଡ଼ୁକୁ ବହୁତ ଭଲ ପାଆନ୍ତି, ସେ ଛଲେ ବଲେ କୌଶଳ କରି ସେଗୁଡ଼ିକୁ ହାସଲ କଲେ। ଲଡ଼ୁ ଖାଇ ସେ \"ହରିବୋଲ! ହରିବୋଲ!\" ବୋଲି ଚିତ୍କାର କଲେ ଏବଂ କାଖ ବଜାଇ ଏକ ବିଚିତ୍ର ଶବ୍ଦ କଲେ।","wordMeanings":[{"word":"ଛଲେ-ବଲେ","meaning":"ଯେମିତି ହେଉ (ଛଳ ବଳ କରି)"},{"word":"ଲାଡୁ ଖାୟ","meaning":"ଲଡୁ ଖାଆନ୍ତି"},{"word":"ଶ୍ରୀ-ମଧୁମଙ୍ଗଳ","meaning":"କୃଷ୍ଣଙ୍କ ବନ୍ଧୁ ମଧୁମଙ୍ଗଳ"},{"word":"ବଗଲ ବାଜାୟ","meaning":"କାଖ ବଜାନ୍ତି"},{"word":"ଆର ଦେୟ","meaning":"\"ଆହୁରି ଦିଅ\""},{"word":"ହରି-ବୋଲ","meaning":"\"ହରିବୋଲ!\"।"}]},{"id":10,"lyric":"ରାଧିକାଦି ଗନେ ହେରି’ ନୟନେର କୋନେ ।\nତୃପ୍ତ ହ’ୟେ ଖାୟ କୃଷ୍ଣ ଯଶୋଦା ଭବନେ ।।୧୦।।","translation":"ରାଧାରାଣୀ ଏବଂ ତାଙ୍କ ସଖୀମାନଙ୍କୁ ଆଖି କୋଣରେ ଚାହିଁ ଚାହିଁ କୃଷ୍ଣ ମାତା ଯଶୋଦାଙ୍କ ଘରେ ଅତି ତୃପ୍ତିର ସହ ଭୋଜନ କଲେ।","wordMeanings":[{"word":"ରାଧିକାଦି ଗଣେ","meaning":"ଶ୍ରୀରାଧା ଓ ସଖୀମାନଙ୍କୁ"},{"word":"ହେରି'","meaning":"ଦେଖି"},{"word":"ନୟନେର କୋଣେ","meaning":"ଆଖି କୋଣରେ"},{"word":"ତୃପ୍ତ ହୋଇ","meaning":"ସନ୍ତୋଷର ସହିତ"},{"word":"ଖାୟ କୃଷ୍ଣ","meaning":"କୃଷ୍ଣ ଖାଆନ୍ତି"},{"word":"ଯଶୋଦା-ଭବନେ","meaning":"ଯଶୋଦାଙ୍କ ଭବନରେ।"}]},{"id":11,"lyric":"ଭୋଜନାନ୍ତେ ପିୟେ କୃଷ୍ଣ ସୁବାସିତ ବାରି ।\nସବେ ମୁଖ ପ୍ରକ୍ଷାଲୟ ହ’ୟେ ସାରି ସାରି ।।୧୧।।","translation":"ଭୋଜନ ପରେ କୃଷ୍ଣ ଗୋଲାପ ବସିତ ଜଳ ପାନ କଲେ। ତା'ପରେ ସମସ୍ତ ବାଳକମାନେ ଧାଡ଼ି ହୋଇ ଠିଆ ହୋଇ ନିଜର ମୁହଁ ଧୋଇଲେ।","wordMeanings":[{"word":"ଭୋଜନାନ୍ତେ","meaning":"ଭୋଜନ ପରେ"},{"word":"ପିୟେ କୃଷ୍ଣ","meaning":"କୃଷ୍ଣ ପାନ କରନ୍ତି"},{"word":"ସୁବାସିତ ବାରି","meaning":"ସୁବାସିତ ଜଳ"},{"word":"ସବେ","meaning":"ସମସ୍ତ ବନ୍ଧୁ"},{"word":"ମୁଖ ପ୍ରଖାଲୋୟ","meaning":"ମୁହଁ ଧୁଅନ୍ତି"},{"word":"ହୋଇ ସାରି ସାରି","meaning":"ଧାଡ଼ି ହୋଇ।"}]},{"id":12,"lyric":"ହସ୍ତ ମୁଖ ପ୍ରକ୍ଷାଲିୟା ଯତ ସଖାଗନେ ।\nଆନନ୍ଦେ ବିଶ୍ରାମ କରେ ବଲଦେବ ସନେ ।।୧୨।।","translation":"ସମସ୍ତ ଗୋପବାଳକମାନେ ହାତ ଓ ମୁହଁ ଧୋଇବା ପରେ ପରମ ଆନନ୍ଦରେ ପ୍ରଭୁ ବଳରାମଙ୍କ ସହିତ ବିଶ୍ରାମ କଲେ।","wordMeanings":[{"word":"ହସ୍ତ-ମୁଖ","meaning":"ହାତ ଓ ମୁହଁ"},{"word":"ପ୍ରଖାଲିୟା","meaning":"ଧୋଇବା ପରେ"},{"word":"ଜତ ସଖା-ଗଣେ","meaning":"ସମସ୍ତ ଗୋପାଳ ବାଳକ"},{"word":"ଆନନ୍ଦେ","meaning":"ପରମ ଆନନ୍ଦରେ"},{"word":"ବିଶ୍ରାମ କୋରେ","meaning":"ବିଶ୍ରାମ କରନ୍ତି"},{"word":"ବଳଦେବ-ସନେ","meaning":"ବଳରାମଙ୍କ ସହିତ।"}]},{"id":13,"lyric":"ଜାମ୍ବୁଲ ରସାଲ ଆଣେ ତାମ୍ବୁଲ ମସାଲା ।\nତାହା ଖେୟେ କୃଷ୍ଣଚନ୍ଦ୍ର ସୁଖେନିଦ୍ରା ଗେଲା ।।୧୩।।","translation":"ଜାମ୍ବୁଲ ଏବଂ ରସାଲ ନାମକ ଦୁଇ ସଖା କୃଷ୍ଣଙ୍କ ପାଇଁ ଗୁଆ, ସୁଗନ୍ଧିତ ମସାଲା ଏବଂ ଖଇର ମିଶ୍ରିତ ପାନ ଆଣିଲେ। ସେହି ପାନ ଖାଇବା ପରେ ଶ୍ରୀ କୃଷ୍ଣଚନ୍ଦ୍ର ସୁଖରେ ନିଦ୍ରା ଗଲେ।","wordMeanings":[{"word":"ଜମ୍ବୁଲ ରସାଲ","meaning":"ଜମ୍ବୁଳ ଓ ରସାଳ (ସେବକ)"},{"word":"ଆନେ","meaning":"ଆଣନ୍ତି"},{"word":"ତାମ୍ବୁଲ-ମସାଲା","meaning":"ମସଲା ଯୁକ୍ତ ପାନ"},{"word":"ତାହା ଖେୟେ","meaning":"ତାହା ଖାଇ"},{"word":"କୃଷ୍ଣ-ଚନ୍ଦ୍ର","meaning":"କୃଷ୍ଣ"},{"word":"ସୁଖେ","meaning":"ସୁଖରେ"},{"word":"ନିଦ୍ରା ଗେଲା","meaning":"ଶୋଇ ପଡ଼ିଲେ।"}]},{"id":14,"lyric":"ବିଶାଲାଖ ଶିଖିପୁଚ୍ଛ ଚାମର ଢୁଲାୟ ।\nଅପୂର୍ବ ଶଯ୍ୟାୟ କୃୃଷ୍ଣ ସୁଖେ ନିଦ୍ରାଯାୟ ।।୧୪।।","translation":"କୃଷ୍ଣ ଏକ ସୁନ୍ଦର ଶଯ୍ୟାରେ ସୁଖଦ ନିଦ୍ରା ଯାଉଥିବା ବେଳେ, ତାଙ୍କ ସେବକ ବିଶାଳାକ୍ଷ ମୟୂର ପୁଚ୍ଛର ଚାମରରେ ତାଙ୍କୁ ବିଞ୍ଚିଲେ।","wordMeanings":[{"word":"ବିଶାଲାକ୍ଷ","meaning":"ବିଶାଳାକ୍ଷ (ସେବକ)"},{"word":"ଶିଖି-ପୁଚ୍ଛ-ଚାମର","meaning":"ମୟୂର ପୁଚ୍ଛ ଚାମର"},{"word":"ଧୁଲାୟ","meaning":"ବିଞ୍ଚନ୍ତି"},{"word":"ଅପୂର୍ବ ଶଯ୍ୟାୟ","meaning":"ଅପୂର୍ବ ଶଯ୍ୟାରେ"},{"word":"କୃଷ୍ଣ","meaning":"କୃଷ୍ଣ"},{"word":"ସୁଖେ","meaning":"ସୁଖରେ"},{"word":"ନିଦ୍ରା ଯାୟ","meaning":"ନିଦ୍ରା ଯାଆନ୍ତି।"}]},{"id":15,"lyric":"ଯଶୋମତୀ ଆଜ୍ଞା ପେୟେ ଧନିଷ୍ଠା - ଆନୀତ ।\nଶ୍ରୀକୃଷ୍ଣପ୍ରସାଦ ରାଧା ଭୁଞ୍ଜେ ହୟେ ପ୍ରୀତ ।।୧୫।।","translation":"ମାତା ଯଶୋଦାଙ୍କ ଅନୁରୋଧରେ, ଧନିଷ୍ଠା ସଖୀ କୃଷ୍ଣଙ୍କ ଥାଳିରେ ବଳିଥିବା ପ୍ରସାଦ ଶ୍ରୀମତୀ ରାଧାରାଣୀଙ୍କ ପାଖକୁ ଆଣିଲେ, ଯାହାକୁ ସେ ଅତି ଆନନ୍ଦର ସହ ଗ୍ରହଣ କଲେ।","wordMeanings":[{"word":"ଯଶୋମତୀ-ଆଜ୍ଞା","meaning":"ମାତା ଯଶୋଦାଙ୍କ ଆଜ୍ଞା"},{"word":"ପେ'ୟେ","meaning":"ପାଇ"},{"word":"ଧନିଷ୍ଠା-ଆନୀତୋ","meaning":"ଧନିଷ୍ଠାଙ୍କ ଦ୍ୱାରା ଅଣାଯାଇଥିବା"},{"word":"ଶ୍ରୀ-କୃଷ୍ଣ-ପ୍ରସାଦ","meaning":"କୃଷ୍ଣଙ୍କ ପ୍ରସାଦ"},{"word":"ରାଧା","meaning":"ଶ୍ରୀମତୀ ରାଧାରାଣୀ"},{"word":"ଭୁଞ୍ଜେ","meaning":"ଭୋଜନ କରନ୍ତି"},{"word":"ହୋଇ ପ୍ରୀତୋ","meaning":"ଅତି ଆନନ୍ଦରେ।"}]},{"id":16,"lyric":"ଲଲିତାଦି ସଖୀଗଣ ଅବଶେଷ ପାୟ ।\nମନେ ମନେ ସୁଖେ ରାଧା-କୃଷ୍ଣ-ଗୁଣ ଗାୟ ।।୧୬।।","translation":"ଲଳିତା ଦେବୀ ଏବଂ ଅନ୍ୟ ସଖୀମାନେ ମଧ୍ୟ ସେହି ଅବଶେଷ ପ୍ରସାଦ ପାଇଲେ ଏବଂ ନିଜ ହୃଦୟ ମଧ୍ୟରେ ଅତି ଉଲ୍ଲାସର ସହ ରାଧା-କୃଷ୍ଣଙ୍କ ମହିମା ଗାନ କଲେ।","wordMeanings":[{"word":"ଲଳିତାଦି","meaning":"ଲଳିତା ଆଦି"},{"word":"ସଖୀ-ଗଣ","meaning":"ସଖୀମାନେ"},{"word":"ଅବଶେଷ ପାୟ","meaning":"ଅବଶେଷ ପ୍ରସାଦ ପାଆନ୍ତି"},{"word":"ମନେ ମନେ","meaning":"ମନେ ମନେ"},{"word":"ସୁଖେ","meaning":"ସୁଖରେ"},{"word":"ରାଧା-କୃଷ୍ଣ-ଗୁଣ","meaning":"ରାଧା-କୃଷ୍ଣଙ୍କ ଗୁଣ"},{"word":"ଗାୟ","meaning":"ଗାନ କରନ୍ତି।"}]},{"id":17,"lyric":"ହରିଲୀଲା ଏକମାତ୍ର ଯାହାର ପ୍ରମୋଦ ।\nଭୋଗାରତି ଗାୟ ସେଇ ଭକତିବିନୋଦ ।।୧୭।।","translation":"ଶ୍ରୀଲ ଭକ୍ତିବିନୋଦ ଠାକୁର, ଯାହାଙ୍କର ଏକମାତ୍ର ଆନନ୍ଦ ହେଉଛି ଭଗବାନ ଶ୍ରୀହରିଙ୍କର ଲୀଲା, ସେ ଏହି ଭୋଗ-ଆରତି ସଙ୍ଗୀତ ଗାନ କରୁଛନ୍ତି।","wordMeanings":[{"word":"ହରି-ଲୀଲା","meaning":"ଭଗବାନଙ୍କ ଲୀଳା"},{"word":"ଏକ-ମାତ୍ର","meaning":"ଏକମାତ୍ର"},{"word":"ଯାହାର","meaning":"ଯାହାଙ୍କର"},{"word":"ପ୍ରମୋଦ","meaning":"ଆନନ୍ଦ"},{"word":"ଭୋଗାରତି","meaning":"ଏହି ଭୋଗ ଆଳତି ଗୀତ"},{"word":"ଗାୟ","meaning":"ଗାଆନ୍ତି"},{"word":"ଠାକୁର ଭକ୍ତିବିନୋଦ","meaning":"ଠାକୁର ଭକ୍ତିବିନୋଦ।"}]}]}$json$,
    'COMPLETED'
)
